import { parseFormula } from './parse.js'
import { Evaluator } from './eval.js'
import { parseAddress, colIndex, colName } from './addr.js'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'values' && mode !== 'deps') {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cells = new Map()
for (let i = 0; i < lines.length; i++) {
  const s = lines[i].replace(/^[ \t]+/, '')
  if (s === '' || s[0] === '#') continue
  const m = /^[^ \t]*/.exec(s)
  const raw = m[0]
  const content = s.slice(raw.length).replace(/^[ \t]+/, '')
  const addr = parseAddress(raw)
  if (!addr) {
    process.stderr.write(`error: line ${i + 1}: invalid cell address ${raw}\n`)
    process.exit(2)
  }
  if (cells.has(addr.key)) {
    process.stderr.write(`error: line ${i + 1}: cell ${raw} is declared twice\n`)
    process.exit(2)
  }
  cells.set(addr.key, { addr, content, ast: content[0] === '=' ? parseFormula(content.slice(1)) : null })
}

const sorted = [...cells.values()].sort((a, b) => a.addr.col - b.addr.col || a.addr.row - b.addr.row)
const out = []
if (mode === 'values') {
  const ev = new Evaluator(cells)
  for (const c of sorted) out.push(`${c.addr.key}=${ev.format(ev.get(c.addr.key))}`)
} else {
  for (const c of sorted) {
    let s = `${c.addr.key}:`
    if (c.ast) {
      const set = new Map()
      collect(c.ast, set)
      const l = [...set.values()].sort((a, b) => a.col - b.col || a.row - b.row)
      for (const a of l) s += ' ' + a.key
    }
    out.push(s)
  }
}
process.stdout.write(out.map((l) => l + '\n').join(''))

function collect(n, set) {
  if (!n) return
  switch (n.t) {
    case 'ref': {
      const a = parseAddress(n.name)
      if (a) set.set(a.key, a)
      break
    }
    case 'range': {
      const a = parseAddress(n.a), b = parseAddress(n.b)
      if (a && b) {
        for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++)
          for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) {
            const key = colName(c) + r
            set.set(key, { key, col: c, row: r })
          }
      }
      break
    }
    case 'bin': collect(n.l, set); collect(n.r, set); break
    case 'un': collect(n.e, set); break
    case 'call': for (const a of n.args) collect(a, set); break
  }
}
